MIG.LEADS = [["L301","contractor","بتروجت","","تسجيل الموردين لدى بتروجت – مواد ومعدات مشروعات البترول والغاز والبنية التحتية","","","محافظة القاهرة","—","غير معلنة","بتروجت من أكبر شركات المقاولات العامة والإنشاءات البترولية في مصر، وبتشتري مواد ومعدات مشروعاتها من الموردين المسجّلين على بوابة الموردين بتاعتها. سجّل مصنعك من البوابة الرسمية علشان يدخل قايمة مورديهم.","https://www.petrojet.com.eg/vendor/vendor_section/login?lang=en"],["L302","contractor","سيمنز موبيليتي","r018","تسجيل اهتمام الموردين والمقاولين من الباطن بمشروع القطار الكهربائي السريع في مصر","","","محافظة مطروح","—","غير معلنة","سيمنز موبيليتي فاتحة نموذج للموردين والمقاولين المهتمين بالشغل في مشروع القطار السريع في مصر، يكتبوا فيه منتجاتهم وخدماتهم. النموذج تسجيل اهتمام ومش دعوة لتقديم عطاء.","https://www.mobility.siemens.com/global/en/portfolio/references/moving-egypt/supplier.html"],["L303","consultant","إنبي للهندسة","","تسجيل الموردين لدى إنبي – مواد ومعدات مشروعات البترول والصناعات التحويلية","","","محافظة القاهرة","—","غير معلنة","إنبي شركة هندسة وتصميم وتوريد وإنشاء لمشروعات البترول والصناعات التحويلية، وبتحدد مواصفات المواد وبتشتريها من الموردين المسجّلين عندها. التسجيل الجديد من زر «Apply For Registration» على بوابة الموردين الرسمية.","https://enppisuppliers.enppi.com/supplier_registration/"]];
